solution:
use xiom.io;

type Point = {
  x: Int;
  y: Int;
}

fn origin() -> Point {
  return Point{ x: 0; y: 0; };
}

fn Point.move(self, dx: Int, dy: Int) {
  x = x + dx;
  y = y + dy;
}

fn Point.reflect(self) {
  x = -x;
  y = -y;
}

fn main() -> Int {
  var p = origin();
  p.move(5, 12);
  p.reflect();
  return p.x + p.y;
}
